<script>
  export let data;
  const money = (amount, currency) => new Intl.NumberFormat('en-KE', { style: 'currency', currency: currency || 'KES', maximumFractionDigits: 0 }).format(Number(amount || 0));
  const copy = (item) => item.release?.edition_size ? `Copy ${String(item.edition_number ?? 1).padStart(2, '0')}/${item.release.edition_size}` : 'Open Edition';
</script>
<svelte:head><title>Collector Market — Noizes Exchange</title></svelte:head>
<main class="market"><p class="eyebrow">Noizes Exchange</p><h1>Collector Market</h1><p class="lede">Authenticated editions offered by their current custodians.</p><nav><a href="/exchange">Discover</a><a class="active" href="/exchange/collector-market">Collector Market</a><a href="/exchange/provenance">Provenance Records</a></nav><div class="tools"><span>Verified authenticated copies</span><a class:chosen={data.sort === 'recent'} href="/exchange/collector-market?sort=recent">Recently listed</a><a class:chosen={data.sort === 'price'} href="/exchange/collector-market?sort=price">Price: low to high</a></div>{#if data.error}<p class="notice">{data.error}</p>{/if}<div class="grid">{#each data.listings as item}<article>{#if item.cover_url}<img src={item.cover_url} alt={`${item.release?.title} artwork`} />{:else}<div class="art">NZ</div>{/if}<div class="body"><p class="artist">{item.release?.artist_name}</p><h2>{item.release?.title}</h2><p class="chip">▣ {copy(item)}</p><p class="registry">◈ Registry verification available<br/>▱ Public provenance record</p><p class="price">{money(item.price_paid, item.currency)} <span>Offers open</span></p><a class="cta" href={`/exchange/copy/${item.id}`}>View copy →</a></div></article>{/each}</div>{#if !data.listings.length}<p class="empty">No authenticated copies are accepting offers yet.</p>{/if}</main>
